import { getAllProducts } from '@/lib/db';
import { revalidateTag } from 'next/cache';

// Child component with 'use cache' directive for product data caching
async function ProductList() {
  'use cache';
  const cacheTag = 'products';

  // Fetch product data - this will be cached with the "products" tag
  const products = await getAllProducts();

  return (
    <div style={{ marginBottom: '2rem' }}>
      <h2>Product Listing (Cached)</h2>
      <p style={{ fontSize: '0.875rem', color: '#666', marginBottom: '1rem' }}>
        Data fetched at: {new Date().toLocaleTimeString()}
      </p>
      <ul style={{ listStyle: 'none', padding: 0 }}>
        {products.map((product) => (
          <li
            key={product.id}
            style={{
              padding: '0.75rem',
              marginBottom: '0.5rem',
              border: '1px solid #ddd',
              borderRadius: '4px',
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'center'
            }}
          >
            <span style={{ fontWeight: '500' }}>{product.name}</span>
            <span style={{ color: '#0070f3' }}>${product.price}</span>
          </li>
        ))}
      </ul>
    </div>
  );
}

// Cache invalidation form component
function CacheInvalidationForm() {
  // Server action to invalidate the "products" cache
  async function invalidateProductCache() {
    'use server';

    // Invalidate the cache tagged with "products"
    revalidateTag('products');

    console.log('Cache invalidated for tag: products at', new Date().toISOString());
  }

  return (
    <form action={invalidateProductCache}>
      <div style={{
        padding: '1rem',
        backgroundColor: '#f5f5f5',
        borderRadius: '4px',
        marginBottom: '1rem'
      }}>
        <h3 style={{ marginTop: 0 }}>Cache Management</h3>
        <p style={{ fontSize: '0.875rem', color: '#666', marginBottom: '1rem' }}>
          Click the button below to invalidate the products cache and trigger a fresh data fetch.
        </p>
        <button
          type="submit"
          style={{
            padding: '0.5rem 1rem',
            backgroundColor: '#0070f3',
            color: 'white',
            border: 'none',
            borderRadius: '4px',
            cursor: 'pointer',
            fontWeight: '500'
          }}
        >
          Invalidate Cache
        </button>
      </div>
    </form>
  );
}

export default function Page() {
  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '2rem' }}>
      <h1>Product Catalog with Smart Caching</h1>
      <p style={{ marginBottom: '2rem', color: '#666' }}>
        This page demonstrates Next.js caching with selective invalidation using cache tags.
      </p>

      <CacheInvalidationForm />
      <ProductList />

      <div style={{
        marginTop: '2rem',
        padding: '1rem',
        backgroundColor: '#fffbeb',
        borderRadius: '4px',
        fontSize: '0.875rem'
      }}>
        <h3 style={{ marginTop: 0 }}>How it works:</h3>
        <ul style={{ marginBottom: 0 }}>
          <li>The ProductList component uses the <code>'use cache'</code> directive to cache fetched data</li>
          <li>Data is tagged with "products" for selective invalidation</li>
          <li>The form's server action calls <code>revalidateTag('products')</code> to invalidate only product-related cache</li>
          <li>After invalidation, the next render will fetch fresh data from the database</li>
          <li>Refresh the page to see the cached timestamp - it won't change until you invalidate</li>
        </ul>
      </div>
    </div>
  );
}

